import{n as e}from"./index-o5Rqz6RD.js";var t=e(`<section id=cold-signing class="section-container border-b border-border py-20"><div class="font-mono text-xs font-semibold letter-spacing-0.12em text-dim2 uppercase mb-5">Recommended</div><h2 class="text-3xl font-bold text-text-em mb-6">Zigner: Air-Gapped Cold Signer</h2><p class="text-lg text-dim max-w-2xl mb-12">The recommended security posture pairs Zafu with Zigner, an air-gapped cold signer running on a dedicated phone. Zafu holds only viewing keys, Zigner holds spending keys, and the channel between them is QR codes only.</p><div class="space-y-px bg-border border border-border"><div class=card><h3 class="font-semibold text-text-em mb-2">Air-Gapped</h3><p class="text-sm text-dim">Spending keys never leave your signer device. No USB, no network. QR-only signing.</p></div><div class=card><h3 class="font-semibold text-text-em mb-2">QR-Based</h3><p class="text-sm text-dim">Sign Zafu transactions via camera. Display QR response. Simple, secure, completely offline.</p></div><div class=card><h3 class="font-semibold text-text-em mb-2">FROST Multisig</h3><p class="text-sm text-dim">Perform t-of-n threshold signing. DKG via QR codes. Penumbra and Zcash compatible.</p></div><div class=card><h3 class="font-semibold text-text-em mb-2">Hot/Cold Split</h3><p class="text-sm text-dim">Zafu holds viewing keys. Zigner holds spending keys. Perfect separation of concerns.</p></div></div><div class="mt-12 flex gap-3"><a href=https://github.com/rotkonetworks/zafu/releases class=btn-primary>Get Zigner Firmware</a><a href=https://docs.zafu.pro class=btn-outline>Documentation`);function n(){return t()}export{n as default};